# -*- coding: utf-8 -*-
"""Année 1970 : 30 dossiers. Narration en français, deux marionnettes :
A = l'Archiviste (Henri), R = la Reporter (Denise).
Chaque réplique : (qui, texte, titre_à_l'écran, options)
options : n (grand chiffre), nl (légende du chiffre), m (motif), mood (shock|anger|sad|joy), stamp
Les faits sont volontairement prudents ; sources de référence : histoire générale 1970.
"""

def L(who, text, h, **o):
    return dict(who=who, text=text, h=h, **o)

